'use client'

import {
  LayoutDashboard,
  ShoppingCart,
  Boxes,
  BarChart2,
  Settings,
  BoxIcon,
} from 'lucide-react'
import Image from 'next/image'
import Link from 'next/link'
import { usePathname } from 'next/navigation'
import LogoutDialog from './LogoutDialog'

const sidebarItems = [
  {
    icon: <LayoutDashboard size={18} />,
    text: 'Dashboard',
    href: '/seller-dashboard/dashboard',
  },
  {
    icon: <ShoppingCart size={18} />,
    text: 'Order',
    href: '/seller-dashboard/order',
  },
  {
    icon: <Boxes size={18} />,
    text: 'Active Product List',
    href: '/seller-dashboard/active-products',
  },
  {
    icon: <BoxIcon size={18} />,
    text: 'Pending Product List',
    href: '/seller-dashboard/products',
  },
  {
    icon: <BarChart2 size={18} />,
    text: 'My Sales',
    href: '/seller-dashboard/sales',
  },
  {
    icon: <Settings size={18} />,
    text: 'Settings',
    href: '/seller-dashboard/settings',
  },
]

function SidebarItem({
  icon,
  text,
  href,
  active,
}: {
  icon: React.ReactNode
  text: string
  href: string
  active?: boolean
}) {
  return (
    <Link href={href} className="block mb-3">
      <div
        className={`flex items-center gap-3 px-4 py-2 rounded-md cursor-pointer ${
          active
            ? 'bg-[#797068] text-white font-semibold'
            : 'hover:bg-gray-700/60 text-gray-200'
        }`}
      >
        {icon}
        <span className="text-sm">{text}</span>
      </div>
    </Link>
  )
}

export default function Sidebar() {
  const pathname = usePathname()

  return (
    <aside className="w-[250px] bg-[#1C2228] text-white flex flex-col">
      <div className="h-[64px] flex items-center justify-center px-2 pt-6 mb-2">
        <Image
          src="/images/dashboard_header.png"
          alt="FASTLANE Logo"
          width={280}
          height={65}
          priority
          className="h-12 w-[300px] object-contain"
        />
      </div>
      <nav className="flex-1 px-4 py-4">
        <div className="space-y-6">
          {sidebarItems.map((item) => (
            <SidebarItem
              key={item.text}
              {...item}
              active={pathname === item.href}
            />
          ))}
        </div>
      </nav>

      <div className="border-t pb-4 px-2 border-gray-700">
        <LogoutDialog />
      </div>
    </aside>
  )
}
