'use client'

import { useGetUserProfile } from '@/lib/handleAllGetRequests'
import Image from 'next/image'
import Link from 'next/link'

export default function UserHeader() {
  const { data: profile, isLoading } = useGetUserProfile()

  if (isLoading) {
    return (
      <div className="flex items-center gap-3 animate-pulse">
        <div className="h-4 w-24 bg-gray-400 rounded"></div>
        <div className="h-12 w-12 bg-gray-500 rounded-full"></div>
      </div>
    )
  }

  return (
    <div className="flex items-center gap-3">
      <span className="text-white font-semibold leading-[120%]">
        {profile?.name || 'User'}
      </span>
      <Link href={'/seller-dashboard/settings'}>
        <div className="cursor-pointer">
          <Image
            src={profile?.profileImage || '/images/demoUser.png'}
            alt={profile?.name || 'User'}
            width={48}
            height={48}
            className="h-12 w-12 rounded-full object-cover"
          />
        </div>
      </Link>
    </div>
  )
}
